import{_ as n,l as o,o as r,c as s,v as d,p as E,x as i,d as t,i as R,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"时间加权对资金加权","description":"","frontmatter":{"title":"时间加权对资金加权","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/twr-vs-mwr.md","filePath":"quant/twr-vs-mwr.md","lastUpdated":1789023840000}'),B={name:"quant/twr-vs-mwr.md"};function h(W,a,u,T,m,f){const l=o("Mermaid");return r(),s("div",null,[a[1]||(a[1]=d('<h1 id="时间加权对资金加权" tabindex="-1">时间加权对资金加权 <a class="header-anchor" href="#时间加权对资金加权" aria-label="Permalink to &quot;时间加权对资金加权&quot;">​</a></h1><div class="epigraph"><p>时间加权收益去掉外部现金流，度量的是组合过程；资金加权（内部收益率）把申购赎回的时点算进去，度量的是投资人实际口袋。</p><footer>—— 实务标准见 GIPS；资金加权的经典实现是 Dietz 一类修正，以及 IRR / MWR</footer></div><p><a href="/quant/active-share">上一课</a>在持仓上问主动有多真。本课的缺口是<strong>收益会计</strong>：同一条净值路径，时间加权（TWR）与资金加权（MWR/IRR）可以差出一截。TWR 把区间切成现金流之间的子段，每段收益率链式相乘，经理不能因「刚好在低点被申购」而受罚或受奖。MWR 是使折现现金流为零的收益率，投资人追涨杀跌时 MWR 低于 TWR——正是 <a href="/quant/fund-flows-chasing">基金流追逐</a> 的会计对应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>营销用 TWR 与基准比（契约对象是过程）。投委会用 MWR 问「我们这些钱到底赚了多少」。两者都对，对象不同。问题是混用：用 TWR 宣传技能，却用高峰 AUM 收管理费；投资人的 MWR 已经更差。GIPS 要求公司级用 TWR，对分离账户等也规定现金流处理。Modified Dietz 用期中加权近似 IRR，大额现金流时近似变差，应改真 IRR 或更细的子区间。</p><p>与费用：激励费按份额净值（接近 TWR 路径）计提，但大进大出改变谁付了费。均衡化条款存在，就是因为 TWR 公平与 MWR 现实打架。</p><h3 id="杠杆与日内现金流" tabindex="-1">杠杆与日内现金流 <a class="header-anchor" href="#杠杆与日内现金流" aria-label="Permalink to &quot;杠杆与日内现金流&quot;">​</a></h3><p>日内融资、期货保证金、同一日多笔申赎，使「日频 TWR」仍含近似。对冲基金与 SMA 必须写清估值时点。用月末净值加月中现金流的 Dietz，在主题狂热期会系统性偏。</p><p><span class="marginnote">私募的 J 曲线让早期 MWR 极差、后期才回正；那不是公开市场 TWR 的对象。本课只管有开放净值的组合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TWR：每个现金流时点估值，子段 \\((V_e-V_b-CF)/V_b\\)，再几何连接。MWR：解 IRR 或 Modified Dietz。报告：两者并列，加上平均 AUM。对照：若 TWR 高、MWR 低，流在伤害投资人，经理的「技能」没有进口袋。基准也要同一套会计，否则 TE 课的 \\(R_p-R_b\\) 没有定义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>外部现金流的时点由投资人（或渠道）决定。过程技能反映在 TWR；择时申赎反映在 TWR−MWR 的差。凸性流使差为负：钱在高点进来、低点出去。这与再平衡溢价、波动拖累都是路径会计，对象不同。</p>',13)),(r(),E(p,null,{default:i(()=>[R(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Path%5B%22%E5%87%80%E5%80%BC%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20TWR%5B%22%E6%97%B6%E9%97%B4%E5%8A%A0%E6%9D%83%20%E8%BF%87%E7%A8%8B%E6%8A%80%E8%83%BD%22%5D%0A%20%20CF%5B%22%E5%A4%96%E9%83%A8%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%20--%3E%20MWR%5B%22%E8%B5%84%E9%87%91%E5%8A%A0%E6%9D%83%20%E5%8F%A3%E8%A2%8B%E7%BB%93%E6%9E%9C%22%5D%0A%20%20Chase%5B%22%E8%BF%BD%E6%B6%A8%E6%9D%80%E8%B7%8C%22%5D%20--%3E%20Gap%5B%22MWR%20%E4%BD%8E%E4%BA%8E%20TWR%22%5D%0A%20%20TWR%20--%3E%20Fee%5B%22%E8%B4%B9%E5%B8%B8%E6%8C%89%E5%87%80%E5%80%BC%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"本课不写如何用估值时点操纵 TWR。加密与按块申赎的产品要另写规则。下一课从基金级收益再往下拆到交易。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"TWR 度量过程，MWR 度量投资人口袋；契约对象要写清。"),e("li",null,"追逐流使 MWR 系统性低于 TWR。"),e("li",null,"基准、费用、TE 必须与同一套会计对齐。"),e("li",null,"出处：GIPS；Dietz 类方法；流与口袋结果对照 Sirri–Tufano / Berk–Green。")],-1))])}const c=n(B,[["render",h]]);export{M as __pageData,c as default};
